insert into users (email, name, passwordHash, role)
     values ('admin@millrow.coffee', 'Millrow Admin', crypt('millrow-admin', genSalt('bf', 12)), 'admin');

insert into collections (id, slug, name, tagline, description, position)
     values ('57460cb6-98a5-426a-8df4-49ff8c2ac4f2', 'single-origin', 'Single Origin', 'One farm, one lot, one season.', 'Coffees from a single farm or washing station, roasted light enough to taste where they came from. We buy these direct and rotate them as harvests come in.', 0);
insert into collections (id, slug, name, tagline, description, position)
     values ('7bb114fa-1011-4150-b2ae-03f231776d90', 'blends', 'Blends', 'Built for every morning.', 'Blends we roast every week and keep tasting the same, so the cup you liked in March is the cup you get in October. Good as espresso, good in a drip machine.', 1);
insert into collections (id, slug, name, tagline, description, position)
     values ('aac695a0-080b-4d57-ba06-12599accfc94', 'gear', 'Gear', 'Tools we use at the roastery.', 'The drippers, kettles and grinders on our own bar. Nothing here we have not brewed with for a year.', 2);

insert into products (id, collectionId, slug, name, tagline, description, notes, origin, process, roast, featured, position)
     values ('127af7ed-8656-4223-b3d9-1fdc94e8643f', '57460cb6-98a5-426a-8df4-49ff8c2ac4f2', 'ethiopia-guji-hambela', 'Ethiopia Guji Hambela', 'Blueberry, jasmine, cocoa nib', 'Dried whole on raised beds at the Hambela washing station, this natural lot is loud with fruit: blueberry jam up front, a jasmine lift in the middle, and a clean cocoa finish as it cools. Brew it as a pour over to get the florals.', 'Blueberry · Jasmine · Cocoa nib', 'Hambela, Guji, Ethiopia', 'Natural', 'Light', true, 0);
