insert into products (id, collectionId, slug, name, tagline, description, notes, origin, process, roast, featured, position)
     values ('6a13d5b5-15c2-417c-87a5-bf95b2bf9673', '57460cb6-98a5-426a-8df4-49ff8c2ac4f2', 'kenya-nyeri-gatomboya', 'Kenya Nyeri Gatomboya', 'Blackcurrant, grapefruit, cane sugar', 'SL28 and SL34 from the Gatomboya factory, double fermented and dried slowly. Bright and juicy, with a blackcurrant acidity that settles into cane sugar sweetness. Our favorite iced.', 'Blackcurrant · Grapefruit · Cane sugar', 'Nyeri, Kenya', 'Washed', 'Light', true, 1);
