insert into products (id, collectionId, slug, name, tagline, description, notes, origin, process, roast, featured, position)
     values ('8be123db-06ed-4f4b-9f13-372149135ee3', '57460cb6-98a5-426a-8df4-49ff8c2ac4f2', 'colombia-huila-el-paraiso', 'Colombia Huila El Paraíso', 'Red apple, caramel, panela', 'From the Paraíso family farm high in Huila. Round and sweet, with crisp red apple, caramel and a panela finish. Forgiving in any brewer, and the one we hand to people new to single origins.', 'Red apple · Caramel · Panela', 'Huila, Colombia', 'Washed', 'Medium', false, 2);
