     values ('8a556bf2-d236-4df0-b10f-d42cd28eca75', '57460cb6-98a5-426a-8df4-49ff8c2ac4f2', 'guatemala-huehuetenango', 'Guatemala Huehuetenango', 'Milk chocolate, almond, orange', 'A smallholder lot from La Libertad, grown near the Mexican border at 1,700 meters. Milk chocolate and toasted almond, with an orange zest brightness that keeps it lively. Great with milk.', 'Milk chocolate · Toasted almond · Orange', 'La Libertad, Huehuetenango', 'Washed', 'Medium', false, 3);
